#include "DEV_Config.h"
#include "EPD_2in15g.h"
#include "GUI_Paint.h"
#include "fonts.h"
#include <stdlib.h>

#define IMAGE_SIZE ((EPD_2IN15G_WIDTH % 4 == 0) ? (EPD_2IN15G_WIDTH / 4) : (EPD_2IN15G_WIDTH / 4 + 1)) * EPD_2IN15G_HEIGHT

UBYTE *Image;

void setup() {
  Serial.begin(115200);
  Serial.println("Low voltage screen (EN)...");

  if (DEV_Module_Init() != 0) {
    Serial.println("DEV_Module_Init failed!");
    return;
  }
  EPD_2IN15G_Init();

  Image = (UBYTE *)malloc(IMAGE_SIZE);
  if (Image == NULL) {
    Serial.println("Failed to allocate memory!");
    return;
  }

  // Холст: поворот 270, размеры 160x296
  Paint_NewImage(Image, EPD_2IN15G_WIDTH, EPD_2IN15G_HEIGHT, 270, EPD_2IN15G_WHITE);
  Paint_SetScale(4);
  Paint_SelectImage(Image);
  Paint_Clear(EPD_2IN15G_WHITE);

  int W = EPD_2IN15G_HEIGHT;   // 160
  int H = EPD_2IN15G_WIDTH;    // 296

  // ============================================================
  // 1. Чёрная рамка по периметру
  // ============================================================
  Paint_DrawRectangle(0, 0, W - 1, H - 1,
                      EPD_2IN15G_BLACK, DOT_PIXEL_2X2, DRAW_FILL_EMPTY);

  // ============================================================
  // 2. Заголовок LOW VOLTAGE — чёрный текст на белом фоне
  //    ВАЖНО: первый цвет — цвет текста, второй — цвет фона.
  // ============================================================
  Paint_DrawString_EN(5, 10, "LOW VOLTAGE", &Font24,
                      EPD_2IN15G_BLACK, EPD_2IN15G_WHITE);

  // ============================================================
  // 3. Жёлтая область на всю ширину, высота 64 пикселя
  // ============================================================
  int yellow_x1 = 2;
  int yellow_y1 = 44;
  int yellow_x2 = W - 3;
  int yellow_y2 = 44 + 64 - 1;

  Paint_DrawRectangle(yellow_x1, yellow_y1, yellow_x2, yellow_y2,
                      EPD_2IN15G_YELLOW, DOT_PIXEL_1X1, DRAW_FILL_FULL);

  // ============================================================
  // 4. Крупная надпись 195V чёрным поверх жёлтого
  //    Здесь фон — жёлтый (цвет области), текст — чёрный.
  // ============================================================
  Paint_DrawString_EN(15, yellow_y1 + 15, "195V", &Font24,
                      EPD_2IN15G_BLACK, EPD_2IN15G_YELLOW);

  // Чёрный треугольник вниз справа
  int tri_x = 110;
  int tri_y = yellow_y1 + 20;
  int tri_size = 25;
  for (int i = 0; i < tri_size; i++) {
    Paint_DrawLine(tri_x - i, tri_y + i, tri_x + i, tri_y + i,
                   EPD_2IN15G_BLACK, DOT_PIXEL_1X1, LINE_STYLE_SOLID);
  }

  // ============================================================
  // 5. Строка подписей (латиница)
  // ============================================================
  int label_y = 115;
  int col_w = W / 4;

  Paint_DrawString_EN(2,          label_y, "ZAL",      &Font12, EPD_2IN15G_BLACK, EPD_2IN15G_WHITE);
  Paint_DrawString_EN(col_w,      label_y, "SERVER",   &Font12, EPD_2IN15G_BLACK, EPD_2IN15G_WHITE);
  Paint_DrawString_EN(col_w * 2,  label_y, "SPALNYA",  &Font12, EPD_2IN15G_BLACK, EPD_2IN15G_WHITE);
  Paint_DrawString_EN(col_w * 3,  label_y, "SAN UZEL", &Font12, EPD_2IN15G_BLACK, EPD_2IN15G_WHITE);

  // ============================================================
  // 6. Строка процентов
  // ============================================================
  int pct_y = 135;
  int pct_h = 25;

  Paint_DrawString_EN(5, pct_y, "0%", &Font16,
                      EPD_2IN15G_BLACK, EPD_2IN15G_WHITE);

  Paint_DrawRectangle(col_w, pct_y - 2, col_w * 2 - 1, pct_y + pct_h - 2,
                      EPD_2IN15G_RED, DOT_PIXEL_1X1, DRAW_FILL_FULL);
  Paint_DrawString_EN(col_w + 2, pct_y, "30%", &Font16,
                      EPD_2IN15G_WHITE, EPD_2IN15G_RED);

  Paint_DrawRectangle(col_w * 2, pct_y - 2, col_w * 3 - 1, pct_y + pct_h - 2,
                      EPD_2IN15G_YELLOW, DOT_PIXEL_1X1, DRAW_FILL_FULL);
  Paint_DrawString_EN(col_w * 2 + 2, pct_y, "60%", &Font16,
                      EPD_2IN15G_BLACK, EPD_2IN15G_YELLOW);

  Paint_DrawString_EN(col_w * 3 + 2, pct_y, "100%", &Font16,
                      EPD_2IN15G_BLACK, EPD_2IN15G_WHITE);

  // ============================================================
  // 7. Отправляем на дисплей
  // ============================================================
  EPD_2IN15G_Display(Image);

  Serial.println("Done.");
}

void loop() {}
